const HTML = "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>WordFinder</title>\n    <style>\n      :root {\n        --bg: #f3efe5;\n        --paper: rgba(255, 252, 247, 0.84);\n        --paper-strong: rgba(255, 255, 255, 0.95);\n        --ink: #1b2725;\n        --muted: #5d6d69;\n        --line: rgba(26, 82, 73, 0.14);\n        --accent: #145f56;\n        --accent-soft: rgba(20, 95, 86, 0.12);\n        --accent-strong: #0e4f48;\n        --wall: #31403d;\n        --wall-ink: rgba(255, 255, 255, 0.72);\n        --tile: #fffdf9;\n        --tile-active: #d3efe6;\n        --tile-hint: #fff2c8;\n        --tile-invalid: #ffd7d4;\n        --shadow: 0 24px 80px rgba(18, 30, 27, 0.12);\n      }\n\n      * {\n        box-sizing: border-box;\n      }\n\n      [hidden] {\n        display: none !important;\n      }\n\n      body {\n        margin: 0;\n        min-height: 100vh;\n        font-family: Georgia, \"Times New Roman\", serif;\n        color: var(--ink);\n        background:\n          radial-gradient(circle at top left, rgba(20, 95, 86, 0.12), transparent 42%),\n          radial-gradient(circle at bottom right, rgba(198, 151, 92, 0.15), transparent 36%),\n          linear-gradient(180deg, #f7f3ea, var(--bg));\n      }\n\n      button,\n      select,\n      input {\n        font: inherit;\n      }\n\n      button,\n      select,\n      input[type=\"text\"],\n      input[type=\"number\"] {\n        border: 1px solid var(--line);\n        border-radius: 16px;\n        background: rgba(255, 255, 255, 0.92);\n        color: var(--ink);\n      }\n\n      button {\n        min-height: 42px;\n        padding: 10px 14px;\n        font-size: 0.94rem;\n        font-weight: 700;\n        cursor: pointer;\n      }\n\n      button.primary {\n        background: var(--accent);\n        color: white;\n        border-color: transparent;\n      }\n\n      button.secondary {\n        background: rgba(255, 255, 255, 0.96);\n      }\n\n      button.warning {\n        background: #f0c95d;\n        color: #2d2511;\n        border-color: transparent;\n      }\n\n      button.ghost {\n        background: transparent;\n      }\n\n      button:hover,\n      select:hover,\n      input:hover {\n        border-color: rgba(20, 95, 86, 0.28);\n      }\n\n      button:focus-visible,\n      select:focus-visible,\n      input:focus-visible,\n      summary:focus-visible,\n      .tile:focus-visible {\n        outline: 3px solid rgba(20, 95, 86, 0.24);\n        outline-offset: 2px;\n      }\n\n      main {\n        width: min(1240px, calc(100% - 32px));\n        margin: 0 auto;\n        padding: 24px 0 28px;\n        display: grid;\n        gap: 20px;\n      }\n\n      .hero {\n        display: grid;\n        gap: 12px;\n      }\n\n      .hero-bar {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 10px;\n        align-items: center;\n      }\n\n      .eyebrow,\n      .version-chip,\n      .mode-pill,\n      .menu-chip {\n        display: inline-flex;\n        align-items: center;\n        justify-content: center;\n        min-height: 34px;\n        padding: 7px 13px;\n        border-radius: 999px;\n        font-size: 0.8rem;\n        font-weight: 800;\n      }\n\n      .eyebrow {\n        letter-spacing: 0.14em;\n        text-transform: uppercase;\n        color: var(--accent);\n        background: rgba(20, 95, 86, 0.11);\n      }\n\n      .version-chip {\n        background: rgba(27, 39, 37, 0.08);\n      }\n\n      .hero-spacer {\n        flex: 1 1 auto;\n      }\n\n      .menu-chip {\n        background: rgba(255, 255, 255, 0.88);\n        border: 1px solid var(--line);\n        color: var(--accent-strong);\n      }\n\n      .hero-copy {\n        display: grid;\n        gap: 10px;\n        max-width: 76ch;\n      }\n\n      h1 {\n        margin: 0;\n        font-size: clamp(2.8rem, 7vw, 5.2rem);\n        line-height: 0.9;\n        letter-spacing: -0.04em;\n      }\n\n      .subtitle {\n        margin: 0;\n        font-size: 1.04rem;\n        line-height: 1.65;\n        color: var(--muted);\n      }\n\n      .layout {\n        display: grid;\n        gap: 20px;\n        grid-template-columns: minmax(0, 1.16fr) minmax(320px, 0.84fr);\n        align-items: start;\n      }\n\n      .panel {\n        background: var(--paper);\n        border: 1px solid rgba(255, 255, 255, 0.66);\n        border-radius: 30px;\n        box-shadow: var(--shadow);\n        backdrop-filter: blur(14px);\n      }\n\n      .board-panel {\n        padding: 22px;\n      }\n\n      .sidebar {\n        padding: 18px;\n        display: grid;\n        gap: 14px;\n      }\n\n      .board-header {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 10px;\n        justify-content: space-between;\n        align-items: center;\n        margin-bottom: 16px;\n      }\n\n      .mode-pill {\n        background: var(--accent-soft);\n        color: var(--accent);\n      }\n\n      .board-shell {\n        padding: clamp(12px, 2vw, 20px);\n        border-radius: 28px;\n        border: 1px solid var(--line);\n        background:\n          linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(246, 240, 229, 0.98)),\n          repeating-linear-gradient(\n            0deg,\n            rgba(20, 95, 86, 0.018) 0 24px,\n            rgba(20, 95, 86, 0.032) 24px 25px\n          );\n      }\n\n      .board {\n        position: relative;\n        display: grid;\n        gap: 6px;\n        touch-action: none;\n        user-select: none;\n      }\n\n      .tile,\n      .block {\n        aspect-ratio: 1;\n        width: 100%;\n        height: 100%;\n        min-width: 0;\n        min-height: 0;\n        margin: 0;\n        border-radius: var(--tile-radius, 16px);\n      }\n\n      .tile {\n        appearance: none;\n        -webkit-appearance: none;\n        position: relative;\n        display: grid;\n        place-items: center;\n        padding: 0;\n        background: var(--tile);\n        border: 1px solid rgba(20, 95, 86, 0.14);\n        color: var(--ink);\n        box-shadow: inset 0 -10px 20px rgba(20, 95, 86, 0.03);\n      }\n\n      .tile.active {\n        background: var(--tile-active);\n        transform: translateY(-1px);\n      }\n\n      .tile.found {\n        color: white;\n        border-width: 2px;\n      }\n\n      .tile.hinted {\n        box-shadow: inset 0 0 0 2px rgba(240, 201, 93, 0.85);\n      }\n\n      .tile.invalid {\n        background: var(--tile-invalid);\n        animation: shake 240ms ease;\n      }\n\n      .tile.locked {\n        cursor: default;\n      }\n\n      .tile-letter {\n        font-size: var(--tile-font-size, 22px);\n        font-weight: 800;\n        line-height: 1;\n      }\n\n      .tile-index,\n      .path-arrow,\n      .path-end {\n        position: absolute;\n        pointer-events: none;\n      }\n\n      .tile-index {\n        top: 5px;\n        left: 6px;\n        font-size: var(--tile-index-size, 10px);\n        font-weight: 800;\n        color: rgba(27, 39, 37, 0.58);\n      }\n\n      .path-arrow {\n        right: 6px;\n        top: 6px;\n        font-size: var(--tile-arrow-size, 12px);\n        font-weight: 800;\n      }\n\n      .path-end {\n        right: 7px;\n        bottom: 4px;\n        font-size: calc(var(--tile-arrow-size, 12px) + 2px);\n        font-weight: 900;\n      }\n\n      .path-arrow.active,\n      .path-end.active {\n        color: var(--accent);\n      }\n\n      .block {\n        display: grid;\n        place-items: center;\n        border: 1px solid rgba(0, 0, 0, 0.18);\n        background:\n          linear-gradient(180deg, rgba(255, 255, 255, 0.04), transparent),\n          var(--wall);\n        color: var(--wall-ink);\n        font-size: var(--tile-font-size, 18px);\n        font-weight: 800;\n      }\n\n      .path-connector {\n        position: absolute;\n        border-radius: 999px;\n        pointer-events: none;\n        opacity: 0.94;\n      }\n\n      .path-connector.active {\n        background: rgba(20, 95, 86, 0.25);\n      }\n\n      .board-footer {\n        display: grid;\n        gap: 14px;\n        margin-top: 16px;\n      }\n\n      .legend {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 10px 16px;\n        font-size: 0.88rem;\n        color: var(--muted);\n      }\n\n      .legend span {\n        display: inline-flex;\n        align-items: center;\n        gap: 8px;\n      }\n\n      .dot {\n        width: 12px;\n        height: 12px;\n        border-radius: 999px;\n      }\n\n      .notes-strip {\n        display: grid;\n        gap: 12px;\n        grid-template-columns: repeat(2, minmax(0, 1fr));\n      }\n\n      .notes-card,\n      .control-card,\n      .message-box,\n      .stats,\n      .success-banner,\n      .slots,\n      .settings-card {\n        border: 1px solid var(--line);\n        border-radius: 22px;\n        background: rgba(255, 255, 255, 0.74);\n      }\n\n      .notes-card,\n      .control-card,\n      .message-box,\n      .success-banner,\n      .settings-card {\n        padding: 16px;\n      }\n\n      .notes-card p,\n      .settings-subtitle,\n      .helper,\n      .seed-note {\n        margin: 0;\n        font-size: 0.92rem;\n        line-height: 1.58;\n        color: var(--muted);\n      }\n\n      .stats {\n        display: grid;\n        gap: 12px;\n        padding: 14px;\n        grid-template-columns: repeat(3, minmax(0, 1fr));\n      }\n\n      .metric {\n        display: grid;\n        gap: 5px;\n        padding: 12px;\n        border-radius: 18px;\n        background: rgba(246, 240, 229, 0.92);\n        border: 1px solid rgba(20, 95, 86, 0.08);\n      }\n\n      .metric-label {\n        font-size: 0.78rem;\n        font-weight: 800;\n        letter-spacing: 0.08em;\n        text-transform: uppercase;\n        color: var(--muted);\n      }\n\n      .metric-value {\n        font-size: 1.15rem;\n        font-weight: 800;\n      }\n\n      .actions {\n        display: grid;\n        gap: 10px;\n        grid-template-columns: repeat(2, minmax(0, 1fr));\n      }\n\n      .control-card-title {\n        display: block;\n        margin-bottom: 12px;\n        font-size: 0.98rem;\n      }\n\n      .current-path {\n        min-height: 30px;\n        margin: 8px 0 10px;\n        font-size: 1.06rem;\n        font-weight: 800;\n        letter-spacing: 0.08em;\n      }\n\n      .success-banner {\n        background: rgba(227, 247, 239, 0.9);\n      }\n\n      .slots {\n        display: grid;\n        gap: 10px;\n        padding: 14px;\n      }\n\n      .slot {\n        display: grid;\n        gap: 8px;\n        padding: 12px;\n        border-radius: 18px;\n        border: 1px solid rgba(20, 95, 86, 0.08);\n        background: rgba(246, 240, 229, 0.88);\n      }\n\n      .slot.solved {\n        background: rgba(230, 245, 238, 0.86);\n      }\n\n      .slot-header {\n        display: flex;\n        justify-content: space-between;\n        gap: 10px;\n        font-size: 0.8rem;\n        font-weight: 800;\n        color: var(--muted);\n        letter-spacing: 0.06em;\n        text-transform: uppercase;\n      }\n\n      .slot-value {\n        font-size: 1.02rem;\n        font-weight: 700;\n        letter-spacing: 0.08em;\n      }\n\n      .app-menu,\n      .menu-submenu {\n        position: relative;\n      }\n\n      .app-menu > summary,\n      .menu-submenu > summary {\n        list-style: none;\n        cursor: pointer;\n      }\n\n      .app-menu > summary::-webkit-details-marker,\n      .menu-submenu > summary::-webkit-details-marker {\n        display: none;\n      }\n\n      .menu-sheet {\n        position: absolute;\n        right: 0;\n        top: calc(100% + 10px);\n        width: min(300px, calc(100vw - 32px));\n        padding: 12px;\n        border-radius: 24px;\n        background: rgba(255, 255, 255, 0.96);\n        border: 1px solid var(--line);\n        box-shadow: 0 20px 64px rgba(18, 26, 24, 0.18);\n        display: grid;\n        gap: 10px;\n        z-index: 20;\n      }\n\n      .menu-action,\n      .menu-link {\n        width: 100%;\n        min-height: 42px;\n        padding: 10px 14px;\n        border-radius: 16px;\n        border: 1px solid var(--line);\n        background: rgba(250, 248, 243, 0.96);\n        color: var(--ink);\n        font-size: 0.92rem;\n        font-weight: 700;\n        text-align: left;\n        text-decoration: none;\n      }\n\n      .menu-submenu {\n        border-radius: 18px;\n        border: 1px solid var(--line);\n        background: rgba(244, 238, 227, 0.76);\n        padding: 8px;\n        display: grid;\n        gap: 8px;\n      }\n\n      .menu-submenu summary {\n        padding: 6px 8px;\n        font-size: 0.88rem;\n        font-weight: 800;\n      }\n\n      .menu-submenu-links {\n        display: grid;\n        gap: 8px;\n      }\n\n      .settings-overlay {\n        position: fixed;\n        inset: 0;\n        z-index: 40;\n        display: grid;\n        place-items: center;\n        padding: 24px;\n        background: rgba(16, 24, 22, 0.52);\n        backdrop-filter: blur(10px);\n      }\n\n      .settings-dialog {\n        width: min(980px, 100%);\n        max-height: min(88vh, 920px);\n        overflow: auto;\n        padding: 22px;\n        border-radius: 28px;\n        background: var(--paper-strong);\n        border: 1px solid rgba(255, 255, 255, 0.7);\n        box-shadow: 0 36px 120px rgba(18, 26, 24, 0.28);\n      }\n\n      .settings-header {\n        display: flex;\n        justify-content: space-between;\n        gap: 16px;\n        align-items: start;\n        margin-bottom: 18px;\n      }\n\n      .settings-header h2 {\n        margin: 0 0 6px;\n        font-size: clamp(1.8rem, 4vw, 2.5rem);\n        line-height: 0.96;\n      }\n\n      .settings-tabs {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 10px;\n        margin-bottom: 18px;\n      }\n\n      .tab-btn {\n        min-height: 40px;\n        border-radius: 999px;\n        padding: 9px 16px;\n        font-size: 0.9rem;\n      }\n\n      .tab-btn.is-active {\n        background: var(--accent);\n        color: white;\n        border-color: transparent;\n      }\n\n      .settings-panel {\n        display: grid;\n        gap: 16px;\n      }\n\n      .field-grid {\n        display: grid;\n        gap: 14px;\n        grid-template-columns: repeat(2, minmax(0, 1fr));\n      }\n\n      .field {\n        display: grid;\n        gap: 8px;\n      }\n\n      .field label {\n        font-size: 0.88rem;\n        font-weight: 700;\n        color: var(--muted);\n      }\n\n      .field input,\n      .field select {\n        min-height: 42px;\n        padding: 10px 12px;\n        width: 100%;\n      }\n\n      .seed-row {\n        display: grid;\n        gap: 10px;\n        grid-template-columns: minmax(0, 1fr) auto;\n      }\n\n      @keyframes shake {\n        0%, 100% { transform: translateX(0); }\n        20% { transform: translateX(-3px); }\n        40% { transform: translateX(3px); }\n        60% { transform: translateX(-2px); }\n        80% { transform: translateX(2px); }\n      }\n\n      @media (max-width: 980px) {\n        .layout {\n          grid-template-columns: 1fr;\n        }\n\n        h1 {\n          max-width: none;\n        }\n      }\n\n      @media (max-width: 760px) {\n        main {\n          width: min(100%, calc(100% - 18px));\n          padding-top: 18px;\n        }\n\n        .board-panel,\n        .sidebar,\n        .settings-dialog {\n          padding: 16px;\n        }\n\n        .notes-strip,\n        .field-grid,\n        .stats,\n        .actions {\n          grid-template-columns: 1fr;\n        }\n\n        .seed-row {\n          grid-template-columns: 1fr;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <section class=\"hero\">\n        <div class=\"hero-bar\">\n          <div class=\"eyebrow\">Doc rebuild</div>\n          <div class=\"version-chip\" id=\"version-chip\">v00.00.43</div>\n          <div class=\"hero-spacer\"></div>\n          <details class=\"app-menu\" id=\"app-menu\">\n            <summary class=\"menu-chip\">Menu</summary>\n            <div class=\"menu-sheet\">\n              <button class=\"menu-action\" id=\"practice-btn\" type=\"button\">New practice board</button>\n              <button class=\"menu-action\" id=\"settings-open-btn\" type=\"button\">Settings</button>\n              <details class=\"menu-submenu\">\n                <summary>Archived versions</summary>\n                <div class=\"menu-submenu-links\">\n                  <a class=\"menu-link\" href=\"./v3.html\">Open v3</a>\n                  <a class=\"menu-link\" href=\"./v2.html\">Open v2</a>\n                  <a class=\"menu-link\" href=\"./v1.html\">Open v1</a>\n                </div>\n              </details>\n            </div>\n          </details>\n        </div>\n        <div class=\"hero-copy\">\n          <h1>WordFinder</h1>\n          <p class=\"subtitle\">\n            Trace each hidden word as one exact orthogonal path. Use every playable tile exactly once,\n            explore deterministic practice variants, and replay any generated board from its shared seed.\n          </p>\n        </div>\n      </section>\n\n      <section class=\"layout\">\n        <section class=\"panel board-panel\">\n          <div class=\"board-header\">\n            <div class=\"mode-pill\" id=\"mode-pill\">Daily puzzle</div>\n            <div class=\"mode-pill\" id=\"puzzle-pill\">Puzzle</div>\n          </div>\n\n          <div class=\"board-shell\">\n            <div class=\"board\" id=\"board\" aria-label=\"Word grid\"></div>\n          </div>\n\n          <div class=\"board-footer\">\n            <div class=\"legend\">\n              <span><i class=\"dot\" style=\"background: var(--tile-active)\"></i> Active path</span>\n              <span><i class=\"dot\" style=\"background: #2a7b6d\"></i> Solved word</span>\n              <span><i class=\"dot\" style=\"background: var(--tile-hint)\"></i> Hint reveal</span>\n              <span><i class=\"dot\" style=\"background: var(--wall)\"></i> Blocked cell</span>\n            </div>\n\n            <div class=\"notes-strip\">\n              <div class=\"notes-card\">\n                <strong>How to play</strong>\n                <p>\n                  Drag through adjacent letters and release to submit, or tap-build a path and tap\n                  the current end tile again to submit it.\n                </p>\n              </div>\n              <div class=\"notes-card\">\n                <strong>Current build</strong>\n                <p>\n                  Fresh rebuild from the docs, with popup settings, URL-synced full seeds, multiple\n                  blank-layout modes, and archived versions in the top-right menu.\n                </p>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <aside class=\"panel sidebar\">\n          <div class=\"stats\">\n            <div class=\"metric\">\n              <span class=\"metric-label\">Found</span>\n              <span class=\"metric-value\" id=\"found-count\">0 / 0</span>\n            </div>\n            <div class=\"metric\">\n              <span class=\"metric-label\">Hints</span>\n              <span class=\"metric-value\" id=\"hint-count\">0</span>\n            </div>\n            <div class=\"metric\">\n              <span class=\"metric-label\">Time</span>\n              <span class=\"metric-value\" id=\"timer\">00:00</span>\n            </div>\n          </div>\n\n          <div class=\"control-card\">\n            <strong class=\"control-card-title\">Actions</strong>\n            <div class=\"actions\">\n              <button class=\"ghost\" id=\"undo-btn\" type=\"button\">Undo</button>\n              <button class=\"warning\" id=\"hint-btn\" type=\"button\">Hint</button>\n              <button class=\"secondary\" id=\"solve-btn\" type=\"button\">Solve</button>\n              <button class=\"ghost\" id=\"reset-btn\" type=\"button\">Reset</button>\n            </div>\n          </div>\n\n          <div class=\"message-box\">\n            <strong>Current path</strong>\n            <div class=\"current-path\" id=\"current-path\">—</div>\n            <div class=\"helper\" id=\"message-text\">\n              Drag or tap through orthogonally adjacent letters to build an exact stored path.\n            </div>\n          </div>\n\n          <div class=\"success-banner\" id=\"success-banner\" hidden>\n            <strong>Board solved.</strong>\n            <div id=\"success-text\"></div>\n          </div>\n\n          <div class=\"slots\" id=\"slots\"></div>\n        </aside>\n      </section>\n    </main>\n\n    <div class=\"settings-overlay\" id=\"settings-overlay\" hidden>\n      <div class=\"settings-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"settings-title\">\n        <div class=\"settings-header\">\n          <div>\n            <h2 id=\"settings-title\">Game Settings</h2>\n            <p class=\"settings-subtitle\">\n              Keep the main screen focused on gameplay. Use these tabs for display, board identity,\n              and generation mechanics.\n            </p>\n          </div>\n          <button class=\"ghost\" id=\"settings-close-btn\" type=\"button\">Close</button>\n        </div>\n\n        <div class=\"settings-tabs\" role=\"tablist\" aria-label=\"Settings sections\">\n          <button class=\"tab-btn is-active\" id=\"tab-ui-btn\" data-tab=\"ui\" type=\"button\">UI</button>\n          <button class=\"tab-btn\" id=\"tab-game-btn\" data-tab=\"game\" type=\"button\">Game Configuration</button>\n          <button class=\"tab-btn\" id=\"tab-generation-btn\" data-tab=\"generation\" type=\"button\">Board & Word Mechanics</button>\n        </div>\n\n        <section class=\"settings-panel\" id=\"settings-panel-ui\">\n          <div class=\"settings-card\">\n            <strong>Display</strong>\n            <div class=\"field-grid\">\n              <div class=\"field\">\n                <label for=\"color-mode\">Solved colors</label>\n                <select id=\"color-mode\">\n                  <option value=\"hue\">Different hues</option>\n                  <option value=\"saturation\">Different saturation</option>\n                  <option value=\"value\">Different values</option>\n                  <option value=\"palette-citrus-grove\">Citrus Grove</option>\n                  <option value=\"palette-seaside-glass\">Seaside Glass</option>\n                  <option value=\"palette-desert-bloom\">Desert Bloom</option>\n                  <option value=\"palette-berry-market\">Berry Market</option>\n                  <option value=\"palette-forest-canopy\">Forest Canopy</option>\n                  <option value=\"palette-sunset-drive\">Sunset Drive</option>\n                  <option value=\"palette-vintage-poster\">Vintage Poster</option>\n                  <option value=\"palette-candy-shop\">Candy Shop</option>\n                  <option value=\"palette-library-ink\">Library Ink</option>\n                  <option value=\"palette-tropical-punch\">Tropical Punch</option>\n                  <option value=\"palette-harvest-table\">Harvest Table</option>\n                  <option value=\"palette-aurora-pop\">Aurora Pop</option>\n                  <option value=\"palette-espresso-mint\">Espresso Mint</option>\n                  <option value=\"palette-boardwalk\">Boardwalk</option>\n                  <option value=\"palette-studio-paint\">Studio Paint</option>\n                  <option value=\"palette-midnight-neon\">Midnight Neon</option>\n                </select>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section class=\"settings-panel\" id=\"settings-panel-game\" hidden>\n          <div class=\"settings-card\">\n            <strong>Board and Seed</strong>\n            <div class=\"field-grid\">\n              <div class=\"field\">\n                <label for=\"grid-size\">Grid size</label>\n                <select id=\"grid-size\"></select>\n              </div>\n              <div class=\"field\">\n                <label for=\"seed-input\">Seed</label>\n                <div class=\"seed-row\">\n                  <input id=\"seed-input\" type=\"text\" spellcheck=\"false\" autocomplete=\"off\" />\n                  <button class=\"secondary\" id=\"seed-apply-btn\" type=\"button\">Apply seed</button>\n                </div>\n                <div class=\"seed-note\">The active seed is mirrored into the URL as <code>?seed=...</code>.</div>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section class=\"settings-panel\" id=\"settings-panel-generation\" hidden>\n          <div class=\"settings-card\">\n            <strong>Word Rules</strong>\n            <div class=\"field-grid\">\n              <div class=\"field\">\n                <label for=\"word-mode\">Word selection</label>\n                <select id=\"word-mode\">\n                  <option value=\"any\">Any words</option>\n                  <option value=\"contains-text\">Words containing...</option>\n                  <option value=\"starts-with\">Words beginning with...</option>\n                  <option value=\"fixed-length\">Only N-letter words</option>\n                </select>\n              </div>\n              <div class=\"field\" id=\"required-text-field\" hidden>\n                <label for=\"required-text-input\">Required letter or letters</label>\n                <input id=\"required-text-input\" type=\"text\" maxlength=\"12\" spellcheck=\"false\" autocomplete=\"off\" />\n              </div>\n              <div class=\"field\" id=\"start-letter-field\" hidden>\n                <label for=\"start-letter-input\">Starting letter</label>\n                <input id=\"start-letter-input\" type=\"text\" maxlength=\"1\" spellcheck=\"false\" autocomplete=\"off\" />\n              </div>\n              <div class=\"field\" id=\"fixed-length-field\" hidden>\n                <label for=\"fixed-length-input\">Word length N</label>\n                <input id=\"fixed-length-input\" type=\"number\" min=\"4\" max=\"12\" step=\"1\" value=\"5\" />\n              </div>\n            </div>\n          </div>\n\n          <div class=\"settings-card\">\n            <strong>Blank Layout</strong>\n            <div class=\"field-grid\">\n              <div class=\"field\">\n                <label for=\"blank-layout\">Blank layout</label>\n                <select id=\"blank-layout\">\n                  <option value=\"default\">Default</option>\n                  <option value=\"no-blanks\">No blanks</option>\n                  <option value=\"verticals\">Verticals</option>\n                  <option value=\"horizontals\">Horizontals</option>\n                  <option value=\"straights\">Straights</option>\n                  <option value=\"diag-slash\">Diagonals /</option>\n                  <option value=\"diag-backslash\">Diagonals \\</option>\n                  <option value=\"diag-both\">Diagonals both</option>\n                </select>\n              </div>\n              <div class=\"field\" id=\"blank-percent-field\" hidden>\n                <label for=\"blank-percent-input\">Blank percent</label>\n                <input id=\"blank-percent-input\" type=\"number\" min=\"0\" max=\"85\" step=\"1\" value=\"22\" />\n              </div>\n              <div class=\"field\" id=\"blank-count-field\" hidden>\n                <label for=\"blank-count-input\">Blank count</label>\n                <input id=\"blank-count-input\" type=\"number\" min=\"0\" max=\"400\" step=\"1\" value=\"0\" />\n              </div>\n              <div class=\"field\" id=\"blank-char-field\" hidden>\n                <label for=\"blank-char-input\">Blank fill character</label>\n                <input id=\"blank-char-input\" type=\"text\" inputmode=\"text\" maxlength=\"1\" spellcheck=\"false\" autocomplete=\"off\" />\n              </div>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n\n    <script src=\"word-pools.js\"></script>\n    <script>\n      const APP_VERSION = \"v00.00.49\";\n      const GRID_MIN = 4;\n      const GRID_MAX = 20;\n\n      document.title = `WordFinder ${APP_VERSION}`;\n      document.getElementById(\"version-chip\").textContent = APP_VERSION;\n\n      const PALETTE_THEMES = {\n        \"palette-citrus-grove\": [18, 42, 82, 128, 154, 196, 226, 332],\n        \"palette-seaside-glass\": [188, 196, 206, 170, 156, 216, 28, 344],\n        \"palette-desert-bloom\": [16, 28, 40, 336, 318, 144, 196, 224],\n        \"palette-berry-market\": [346, 332, 312, 276, 246, 206, 168, 28],\n        \"palette-forest-canopy\": [118, 130, 146, 164, 186, 34, 20, 220],\n        \"palette-sunset-drive\": [10, 24, 40, 326, 294, 256, 210, 188],\n        \"palette-vintage-poster\": [12, 34, 52, 88, 196, 216, 338, 278],\n        \"palette-candy-shop\": [338, 318, 284, 248, 198, 172, 42, 16],\n        \"palette-library-ink\": [218, 236, 268, 330, 14, 32, 166, 194],\n        \"palette-tropical-punch\": [354, 22, 48, 152, 176, 198, 226, 290],\n        \"palette-harvest-table\": [22, 34, 48, 76, 96, 182, 214, 348],\n        \"palette-aurora-pop\": [164, 184, 208, 238, 274, 308, 340, 34],\n        \"palette-espresso-mint\": [18, 28, 160, 176, 196, 220, 336, 44],\n        \"palette-boardwalk\": [192, 206, 224, 10, 24, 40, 154, 326],\n        \"palette-studio-paint\": [350, 18, 48, 132, 196, 226, 270, 316],\n        \"palette-midnight-neon\": [218, 188, 162, 124, 42, 16, 332, 286]\n      };\n\n      const state = {\n        mode: \"daily\",\n        selectedGridSize: \"5x5\",\n        selectedColorMode: \"value\",\n        selectedWordMode: \"any\",\n        selectedRequiredText: \"\",\n        selectedStartLetter: \"\",\n        selectedFixedLength: 5,\n        selectedBlankLayout: \"default\",\n        selectedBlankPercent: 22,\n        selectedBlankCount: 0,\n        selectedBlankChar: \"\",\n        practiceIndex: 0,\n        currentSeed: \"\",\n        puzzle: null,\n        foundWords: [],\n        hints: {},\n        activePath: [],\n        invalidTiles: [],\n        message: \"Drag or tap through orthogonally adjacent letters to build an exact stored path.\",\n        startTime: Date.now(),\n        timerHandle: null,\n        draggingPointerId: null,\n        gestureExtended: false\n      };\n\n      const els = {\n        appMenu: document.getElementById(\"app-menu\"),\n        board: document.getElementById(\"board\"),\n        slots: document.getElementById(\"slots\"),\n        modePill: document.getElementById(\"mode-pill\"),\n        puzzlePill: document.getElementById(\"puzzle-pill\"),\n        foundCount: document.getElementById(\"found-count\"),\n        hintCount: document.getElementById(\"hint-count\"),\n        timer: document.getElementById(\"timer\"),\n        currentPath: document.getElementById(\"current-path\"),\n        messageText: document.getElementById(\"message-text\"),\n        successBanner: document.getElementById(\"success-banner\"),\n        successText: document.getElementById(\"success-text\"),\n        practiceBtn: document.getElementById(\"practice-btn\"),\n        settingsOpenBtn: document.getElementById(\"settings-open-btn\"),\n        settingsOverlay: document.getElementById(\"settings-overlay\"),\n        settingsCloseBtn: document.getElementById(\"settings-close-btn\"),\n        settingsTabButtons: Array.from(document.querySelectorAll(\".tab-btn\")),\n        settingsPanels: {\n          ui: document.getElementById(\"settings-panel-ui\"),\n          game: document.getElementById(\"settings-panel-game\"),\n          generation: document.getElementById(\"settings-panel-generation\")\n        },\n        gridSize: document.getElementById(\"grid-size\"),\n        seedInput: document.getElementById(\"seed-input\"),\n        seedApplyBtn: document.getElementById(\"seed-apply-btn\"),\n        colorMode: document.getElementById(\"color-mode\"),\n        wordMode: document.getElementById(\"word-mode\"),\n        requiredTextField: document.getElementById(\"required-text-field\"),\n        requiredTextInput: document.getElementById(\"required-text-input\"),\n        startLetterField: document.getElementById(\"start-letter-field\"),\n        startLetterInput: document.getElementById(\"start-letter-input\"),\n        fixedLengthField: document.getElementById(\"fixed-length-field\"),\n        fixedLengthInput: document.getElementById(\"fixed-length-input\"),\n        blankLayout: document.getElementById(\"blank-layout\"),\n        blankPercentField: document.getElementById(\"blank-percent-field\"),\n        blankPercentInput: document.getElementById(\"blank-percent-input\"),\n        blankCountField: document.getElementById(\"blank-count-field\"),\n        blankCountInput: document.getElementById(\"blank-count-input\"),\n        blankCharField: document.getElementById(\"blank-char-field\"),\n        blankCharInput: document.getElementById(\"blank-char-input\"),\n        undoBtn: document.getElementById(\"undo-btn\"),\n        hintBtn: document.getElementById(\"hint-btn\"),\n        solveBtn: document.getElementById(\"solve-btn\"),\n        resetBtn: document.getElementById(\"reset-btn\")\n      };\n\n      function clamp(value, min, max) {\n        return Math.min(max, Math.max(min, value));\n      }\n\n      function toCoord(index, cols) {\n        return [Math.floor(index / cols), index % cols];\n      }\n\n      function toIndex(row, col, cols) {\n        return row * cols + col;\n      }\n\n      function directionBetween(fromIndex, toIndexValue, cols) {\n        const [fromRow, fromCol] = toCoord(fromIndex, cols);\n        const [toRow, toCol] = toCoord(toIndexValue, cols);\n        return [toRow - fromRow, toCol - fromCol];\n      }\n\n      function hashText(text) {\n        let hash = 2166136261;\n        for (const char of text) {\n          hash ^= char.charCodeAt(0);\n          hash = Math.imul(hash, 16777619);\n        }\n        return hash >>> 0;\n      }\n\n      function makeRng(seed) {\n        let value = seed >>> 0;\n        return () => {\n          value = (value * 1664525 + 1013904223) >>> 0;\n          return value / 4294967296;\n        };\n      }\n\n      function randInt(rng, min, max) {\n        return min + Math.floor(rng() * (max - min + 1));\n      }\n\n      function shuffle(array, rng) {\n        const next = [...array];\n        for (let index = next.length - 1; index > 0; index -= 1) {\n          const swap = Math.floor(rng() * (index + 1));\n          [next[index], next[swap]] = [next[swap], next[index]];\n        }\n        return next;\n      }\n\n      function uniqueWords(words) {\n        return [...new Set(words.filter(Boolean).map((word) => String(word).toUpperCase()))];\n      }\n\n      function sanitizeStartLetter(value, fallback = \"\") {\n        const letter = String(value || \"\").replace(/[^a-z]/gi, \"\").slice(0, 1).toUpperCase();\n        return letter || fallback;\n      }\n\n      function sanitizeRequiredText(value, fallback = \"\") {\n        const text = String(value || \"\").replace(/[^a-z]/gi, \"\").slice(0, 12).toUpperCase();\n        return text || fallback;\n      }\n\n      function sanitizeFixedLength(value) {\n        return clamp(Number.parseInt(value, 10) || 5, 4, 12);\n      }\n\n      function sanitizeBlankPercent(value) {\n        return clamp(Number.parseInt(value, 10) || 0, 0, 85);\n      }\n\n      function sanitizeBlankCount(value, rows, cols) {\n        return clamp(Number.parseInt(value, 10) || 0, 0, rows * cols);\n      }\n\n      function sanitizeBlankChar(value) {\n        const text = String(value || \"\").slice(0, 1);\n        if (!text) return \"\";\n        const code = text.charCodeAt(0);\n        return code >= 32 && code <= 126 ? text : \"\";\n      }\n\n      function getUrlSeed() {\n        return new URLSearchParams(window.location.search).get(\"seed\") || \"\";\n      }\n\n      function setUrlSeed(seed) {\n        const url = new URL(window.location.href);\n        if (seed) {\n          url.searchParams.set(\"seed\", seed);\n        } else {\n          url.searchParams.delete(\"seed\");\n        }\n        window.history.replaceState({}, \"\", url);\n      }\n\n      function currentGridSize() {\n        const [rows, cols] = state.selectedGridSize.split(\"x\").map(Number);\n        return { rows, cols };\n      }\n\n      function currentWordSettings() {\n        return {\n          mode: state.selectedWordMode,\n          requiredText: sanitizeRequiredText(state.selectedRequiredText, \"Z\"),\n          startLetter: sanitizeStartLetter(state.selectedStartLetter, \"A\"),\n          fixedLength: sanitizeFixedLength(state.selectedFixedLength)\n        };\n      }\n\n      function blankControlsRelevant(mode) {\n        return mode !== \"default\" && mode !== \"no-blanks\";\n      }\n\n      function currentLayoutSettings(rows = null, cols = null) {\n        const actualRows = rows ?? currentGridSize().rows;\n        const actualCols = cols ?? currentGridSize().cols;\n        const mode = state.selectedBlankLayout;\n        const blankPercent = blankControlsRelevant(mode) ? sanitizeBlankPercent(state.selectedBlankPercent) : 0;\n        const blankCount = blankControlsRelevant(mode) ? sanitizeBlankCount(state.selectedBlankCount, actualRows, actualCols) : 0;\n        const blankChar = blankControlsRelevant(mode) ? sanitizeBlankChar(state.selectedBlankChar) : \"\";\n        return { mode, blankPercent, blankCount, blankChar };\n      }\n\n      function matchesWordMode(word, wordSettings) {\n        switch (wordSettings.mode) {\n          case \"contains-text\":\n            return word.includes(wordSettings.requiredText);\n          case \"starts-with\":\n            return word.startsWith(wordSettings.startLetter);\n          case \"fixed-length\":\n            return word.length === wordSettings.fixedLength;\n          default:\n            return true;\n        }\n      }\n\n      function baseWordsForLength(length) {\n        return uniqueWords((GENERAL_WORD_BANK[String(length)] || []));\n      }\n\n      function getWordCandidatesForLength(length, wordSettings) {\n        if (wordSettings.mode === \"contains-text\") {\n          const specialMatches = Object.entries(SPECIAL_WORD_BANK).flatMap(([mode, lengths]) => {\n            const words = (lengths || {})[String(length)] || [];\n            return mode.startsWith(\"contains-\") ? words : [];\n          });\n          return uniqueWords([\n            ...specialMatches.filter((word) => matchesWordMode(word, wordSettings)),\n            ...baseWordsForLength(length).filter((word) => matchesWordMode(word, wordSettings))\n          ]);\n        }\n        return baseWordsForLength(length).filter((word) => matchesWordMode(word, wordSettings));\n      }\n\n      function allowedWordLengths(wordSettings) {\n        const lengths = [];\n        for (let length = 4; length <= 12; length += 1) {\n          if (getWordCandidatesForLength(length, wordSettings).length > 0) lengths.push(length);\n        }\n        return lengths;\n      }\n\n      function chooseWordLengthsForTotal(totalCells, wordSettings, rng) {\n        const allowed = allowedWordLengths(wordSettings);\n        if (allowed.length === 0) return [];\n        if (wordSettings.mode === \"fixed-length\") {\n          const lengths = [];\n          let remaining = totalCells;\n          while (remaining >= wordSettings.fixedLength) {\n            lengths.push(wordSettings.fixedLength);\n            remaining -= wordSettings.fixedLength;\n          }\n          return lengths;\n        }\n\n        const minLen = allowed[0];\n        const maxLen = allowed[allowed.length - 1];\n        const lengths = [];\n        let remaining = totalCells;\n\n        while (remaining >= minLen) {\n          const candidates = allowed.filter((length) => {\n            if (length > remaining) return false;\n            const leftover = remaining - length;\n            return leftover === 0 || leftover >= minLen;\n          });\n          if (candidates.length === 0) break;\n          const band =\n            lengths.length % 3 === 0 ? minLen + randInt(rng, 0, Math.max(0, Math.min(2, maxLen - minLen))) :\n            lengths.length % 3 === 1 ? Math.floor((minLen + maxLen) / 2) :\n            maxLen - randInt(rng, 0, Math.max(0, Math.min(2, maxLen - minLen)));\n          candidates.sort((a, b) => Math.abs(a - band) - Math.abs(b - band));\n          const pool = candidates.slice(0, Math.min(4, candidates.length));\n          const choice = pool[randInt(rng, 0, pool.length - 1)];\n          lengths.push(choice);\n          remaining -= choice;\n        }\n\n        return lengths;\n      }\n\n      function pickWord(length, slotIndex, seedLabel, wordSettings) {\n        const bank = getWordCandidatesForLength(length, wordSettings);\n        if (bank.length === 0) return \"WORD\".slice(0, length).padEnd(length, \"X\");\n        const seed = hashText(`${seedLabel}:word:${length}:${slotIndex}`);\n        return bank[(seed + slotIndex * 11) % bank.length];\n      }\n\n      function wordSelectionSeedKey(wordSettings) {\n        switch (wordSettings.mode) {\n          case \"contains-text\": return `contains-${wordSettings.requiredText}`;\n          case \"starts-with\": return `starts-${wordSettings.startLetter}`;\n          case \"fixed-length\": return `n-${wordSettings.fixedLength}`;\n          default: return \"any\";\n        }\n      }\n\n      function decodeWordSelectionSeedKey(key) {\n        const normalized = String(key || \"any\");\n        if (normalized === \"z\") return { mode: \"contains-text\", requiredText: \"Z\", startLetter: \"\", fixedLength: 5 };\n        if (normalized === \"x\") return { mode: \"contains-text\", requiredText: \"X\", startLetter: \"\", fixedLength: 5 };\n        if (normalized === \"q\") return { mode: \"contains-text\", requiredText: \"Q\", startLetter: \"\", fixedLength: 5 };\n        if (normalized === \"ing\") return { mode: \"contains-text\", requiredText: \"ING\", startLetter: \"\", fixedLength: 5 };\n        if (normalized === \"mm\") return { mode: \"contains-text\", requiredText: \"MM\", startLetter: \"\", fixedLength: 5 };\n        if (normalized.startsWith(\"contains-\")) {\n          return { mode: \"contains-text\", requiredText: sanitizeRequiredText(normalized.slice(9)), startLetter: \"\", fixedLength: 5 };\n        }\n        if (normalized.startsWith(\"starts-\")) {\n          return { mode: \"starts-with\", requiredText: \"\", startLetter: sanitizeStartLetter(normalized.slice(7)), fixedLength: 5 };\n        }\n        if (normalized.startsWith(\"n-\")) {\n          return { mode: \"fixed-length\", requiredText: \"\", startLetter: \"\", fixedLength: sanitizeFixedLength(normalized.slice(2)) };\n        }\n        return { mode: \"any\", requiredText: \"\", startLetter: \"\", fixedLength: 5 };\n      }\n\n      function layoutSelectionSeedKey(layoutSettings) {\n        const char = sanitizeBlankChar(layoutSettings.blankChar);\n        const charCode = char ? char.charCodeAt(0).toString(16) : \"none\";\n        return [\n          layoutSettings.mode,\n          sanitizeBlankPercent(layoutSettings.blankPercent),\n          layoutSettings.blankCount,\n          charCode\n        ].join(\",\");\n      }\n\n      function decodeLayoutSelectionSeedKey(key, rows, cols) {\n        const [modeToken = \"default\", percentToken = \"22\", countToken = \"0\", charToken = \"none\"] =\n          String(key || \"\").split(\",\");\n        const allowedModes = new Set([\n          \"default\", \"no-blanks\", \"verticals\", \"horizontals\", \"straights\",\n          \"diag-slash\", \"diag-backslash\", \"diag-both\"\n        ]);\n        const mode = allowedModes.has(modeToken) ? modeToken : \"default\";\n        const parsedCharCode = Number.parseInt(charToken, 16);\n        const blankChar =\n          charToken === \"none\" || !Number.isFinite(parsedCharCode) ? \"\" : String.fromCharCode(parsedCharCode);\n        return {\n          mode,\n          blankPercent: sanitizeBlankPercent(percentToken),\n          blankCount: sanitizeBlankCount(countToken, rows, cols),\n          blankChar: sanitizeBlankChar(blankChar)\n        };\n      }\n\n      function simplifySeed(seedValue, fallback = \"practice-0\") {\n        const trimmed = String(seedValue || \"\").trim();\n        return trimmed || fallback;\n      }\n\n      function normalizeSeed(seedValue, fallback = \"practice-0\") {\n        return simplifySeed(seedValue, fallback);\n      }\n\n      function composeGameSeed(baseSeed, rows, cols, wordSettings, layoutSettings) {\n        return [\n          normalizeSeed(baseSeed, \"practice-0\"),\n          `${rows}x${cols}`,\n          wordSelectionSeedKey(wordSettings),\n          layoutSelectionSeedKey(layoutSettings)\n        ].join(\"~\");\n      }\n\n      function parseGridSizeToken(token) {\n        const match = String(token || \"\").match(/^(\\d+)x(\\d+)$/);\n        if (!match) return null;\n        const rows = Number(match[1]);\n        const cols = Number(match[2]);\n        if (!Number.isInteger(rows) || !Number.isInteger(cols)) return null;\n        if (rows < GRID_MIN || rows > GRID_MAX || cols < GRID_MIN || cols > GRID_MAX) return null;\n        return { rows, cols, gridSize: `${rows}x${cols}` };\n      }\n\n      function parseGameSeed(seedValue, fallbackBase = \"practice-0\") {\n        const trimmed = simplifySeed(seedValue, fallbackBase);\n        const [baseSeed = fallbackBase, gridToken = \"\", wordToken = \"\", layoutToken = \"\"] = trimmed.split(\"~\");\n        return { baseSeed: simplifySeed(baseSeed, fallbackBase), gridToken, wordToken, layoutToken, fullSeed: trimmed };\n      }\n\n      function buildDailyBaseSeed() {\n        return `daily-${Math.floor(Date.now() / 86400000)}`;\n      }\n\n      function buildPracticeBaseSeed(variant) {\n        return `practice-${variant}`;\n      }\n\n      function applySeedConfiguration(seedValue, fallbackBase = \"practice-0\") {\n        const parsed = parseGameSeed(seedValue, fallbackBase);\n        const grid = parseGridSizeToken(parsed.gridToken);\n        if (grid) state.selectedGridSize = grid.gridSize;\n        const { rows, cols } = currentGridSize();\n        if (parsed.wordToken) {\n          const word = decodeWordSelectionSeedKey(parsed.wordToken);\n          state.selectedWordMode = word.mode;\n          state.selectedRequiredText = word.requiredText;\n          state.selectedStartLetter = word.startLetter;\n          state.selectedFixedLength = word.fixedLength;\n        }\n        if (parsed.layoutToken) {\n          const layout = decodeLayoutSelectionSeedKey(parsed.layoutToken, rows, cols);\n          state.selectedBlankLayout = layout.mode;\n          state.selectedBlankPercent = layout.blankPercent;\n          state.selectedBlankCount = layout.blankCount;\n          state.selectedBlankChar = layout.blankChar;\n        }\n        return {\n          baseSeed: parsed.baseSeed,\n          rows,\n          cols,\n          mode: parsed.baseSeed.startsWith(\"daily-\") ? \"daily\" : \"practice\",\n          fullSeed: composeGameSeed(parsed.baseSeed, rows, cols, currentWordSettings(), currentLayoutSettings(rows, cols))\n        };\n      }\n\n      function storageKeyFor(puzzle) {\n        return `wordfinder:${puzzle.id}`;\n      }\n\n      function saveState() {\n        if (!state.puzzle) return;\n        localStorage.setItem(\n          storageKeyFor(state.puzzle),\n          JSON.stringify({\n            foundWords: state.foundWords,\n            hints: state.hints,\n            startTime: state.startTime\n          })\n        );\n      }\n\n      function loadStateForPuzzle(puzzle) {\n        try {\n          const raw = localStorage.getItem(storageKeyFor(puzzle));\n          return raw ? JSON.parse(raw) : null;\n        } catch {\n          return null;\n        }\n      }\n\n      function orthNeighbors(index, rows, cols) {\n        const [row, col] = toCoord(index, cols);\n        const next = [];\n        if (row > 0) next.push(index - cols);\n        if (row < rows - 1) next.push(index + cols);\n        if (col > 0) next.push(index - 1);\n        if (col < cols - 1) next.push(index + 1);\n        return next;\n      }\n\n      function countAvailableNeighbors(index, rows, cols, occupiedSet, localSet) {\n        return orthNeighbors(index, rows, cols).filter((neighbor) => !occupiedSet.has(neighbor) && !localSet.has(neighbor)).length;\n      }\n\n      function pathTurnCount(path, cols) {\n        let turns = 0;\n        for (let index = 1; index < path.length - 1; index += 1) {\n          const [dr1, dc1] = directionBetween(path[index - 1], path[index], cols);\n          const [dr2, dc2] = directionBetween(path[index], path[index + 1], cols);\n          if (dr1 !== dr2 || dc1 !== dc2) turns += 1;\n        }\n        return turns;\n      }\n\n      function pathHasTurn(path, cols) {\n        return pathTurnCount(path, cols) > 0;\n      }\n\n      function countTurningPaths(slotPaths, cols) {\n        return slotPaths.reduce((count, path) => count + (pathHasTurn(path, cols) ? 1 : 0), 0);\n      }\n\n      function requiredTurningWordCount(lengthsOrPaths, cols = null) {\n        const lengths = typeof lengthsOrPaths[0] === \"number\"\n          ? lengthsOrPaths\n          : lengthsOrPaths.map((path) => path.length);\n        const eligible = lengths.filter((length) => length >= 3).length;\n        if (eligible === 0) return 0;\n        const total = lengths.length;\n        return Math.min(eligible, Math.max(1, Math.ceil(total * 0.25)));\n      }\n\n      function traversalTurnIndexes(traversal, cols) {\n        const indexes = [];\n        for (let index = 1; index < traversal.length - 1; index += 1) {\n          const [dr1, dc1] = directionBetween(traversal[index - 1], traversal[index], cols);\n          const [dr2, dc2] = directionBetween(traversal[index], traversal[index + 1], cols);\n          if (dr1 !== dr2 || dc1 !== dc2) indexes.push(index);\n        }\n        return indexes;\n      }\n\n      function placeRandomPath(length, occupiedSet, rows, cols, rng, options = {}) {\n        const requireTurn = Boolean(options.requireTurn && length >= 3);\n        const freeCells = [];\n        for (let index = 0; index < rows * cols; index += 1) {\n          if (!occupiedSet.has(index)) freeCells.push(index);\n        }\n        if (freeCells.length < length) return null;\n\n        const startPool = shuffle(freeCells, rng).slice(0, Math.min(60, freeCells.length));\n        for (const start of startPool) {\n          const path = [start];\n          const localSet = new Set([start]);\n\n          function dfs(current, previousDirection = null, hasTurn = false) {\n            if (path.length === length) return !requireTurn || hasTurn;\n            let neighbors = orthNeighbors(current, rows, cols)\n              .filter((neighbor) => !occupiedSet.has(neighbor) && !localSet.has(neighbor))\n              .map((neighbor) => ({\n                neighbor,\n                degree: countAvailableNeighbors(neighbor, rows, cols, occupiedSet, localSet),\n                direction: directionBetween(current, neighbor, cols)\n              }));\n            neighbors.sort((a, b) => {\n              const aTurn = previousDirection && (a.direction[0] !== previousDirection[0] || a.direction[1] !== previousDirection[1]) ? 1 : 0;\n              const bTurn = previousDirection && (b.direction[0] !== previousDirection[0] || b.direction[1] !== previousDirection[1]) ? 1 : 0;\n              if (requireTurn && aTurn !== bTurn) return bTurn - aTurn;\n              return a.degree - b.degree || rng() - 0.5;\n            });\n            for (const { neighbor, direction } of neighbors) {\n              const nextTurn = hasTurn || (previousDirection && (direction[0] !== previousDirection[0] || direction[1] !== previousDirection[1]));\n              localSet.add(neighbor);\n              path.push(neighbor);\n              if (dfs(neighbor, direction, nextTurn)) return true;\n              path.pop();\n              localSet.delete(neighbor);\n            }\n            return false;\n          }\n\n          if (dfs(start)) return path;\n        }\n        return null;\n      }\n\n      function snakeTraversal(rows, cols, rng) {\n        const reverseRows = rng() > 0.5;\n        const reverseCols = rng() > 0.5;\n        const traversal = [];\n        const rowOrder = Array.from({ length: rows }, (_, row) => reverseRows ? rows - 1 - row : row);\n        for (let rowIndex = 0; rowIndex < rowOrder.length; rowIndex += 1) {\n          const row = rowOrder[rowIndex];\n          const leftToRight = rowIndex % 2 === 0 ? !reverseCols : reverseCols;\n          const colsOrder = Array.from({ length: cols }, (_, col) => leftToRight ? col : cols - 1 - col);\n          colsOrder.forEach((col) => traversal.push(toIndex(row, col, cols)));\n        }\n        return traversal;\n      }\n\n      function splitTraversalIntoSlots(traversal, totalCells, wordSettings, cols, rng) {\n        const lengths = chooseWordLengthsForTotal(totalCells, wordSettings, rng);\n        const targetTurningWords = requiredTurningWordCount(lengths);\n        const turnIndexes = traversalTurnIndexes(traversal, cols);\n        const slotPaths = [];\n        const remainingLengths = [...lengths];\n        let offset = 0;\n        let turningWords = 0;\n\n        while (remainingLengths.length > 0) {\n          let chosenIndex = 0;\n          const turnsNeeded = targetTurningWords - turningWords;\n          const nextTurn = turnIndexes.find((turnIndex) => turnIndex > offset);\n\n          if (turnsNeeded > 0 && nextTurn !== undefined) {\n            const minLengthToCrossTurn = nextTurn - offset + 2;\n            const candidates = remainingLengths\n              .map((length, index) => ({ length, index }))\n              .filter(({ length }) => length >= 3 && length >= minLengthToCrossTurn);\n            if (candidates.length) {\n              candidates.sort((a, b) => a.length - b.length || rng() - 0.5);\n              chosenIndex = candidates[0].index;\n            }\n          }\n\n          const [length] = remainingLengths.splice(chosenIndex, 1);\n          if (offset + length > traversal.length) return;\n          const slot = traversal.slice(offset, offset + length);\n          slotPaths.push(slot);\n          if (pathHasTurn(slot, cols)) turningWords += 1;\n          offset += length;\n        }\n        return slotPaths;\n      }\n\n      function targetBlockedForLayout(rows, cols, layoutSettings) {\n        if (layoutSettings.mode === \"no-blanks\") return 0;\n        if (blankControlsRelevant(layoutSettings.mode)) {\n          if (layoutSettings.blankCount > 0) return layoutSettings.blankCount;\n          return Math.round((rows * cols * layoutSettings.blankPercent) / 100);\n        }\n        const ratio =\n          rows >= 18 ? 0.24 :\n          rows >= 14 ? 0.22 :\n          rows >= 10 ? 0.2 : 0.16;\n        return Math.round(rows * cols * ratio);\n      }\n\n      function carveLineSegment(blockedSet, rows, cols, mode, rng, remaining) {\n        const orientations =\n          mode === \"verticals\" ? [\"vertical\"] :\n          mode === \"horizontals\" ? [\"horizontal\"] :\n          mode === \"straights\" ? [\"vertical\", \"horizontal\"] :\n          mode === \"diag-slash\" ? [\"slash\"] :\n          mode === \"diag-backslash\" ? [\"backslash\"] :\n          [\"slash\", \"backslash\"];\n        const orientation = orientations[randInt(rng, 0, orientations.length - 1)];\n        const startRow = randInt(rng, 0, rows - 1);\n        const startCol = randInt(rng, 0, cols - 1);\n        const maxSegment = Math.max(1, Math.min(remaining, Math.floor((rows + cols) / 3)));\n        const length = randInt(rng, 1, Math.max(1, maxSegment));\n        const cells = [];\n        for (let step = 0; step < length; step += 1) {\n          const row =\n            orientation === \"horizontal\" ? startRow :\n            orientation === \"vertical\" ? startRow + step :\n            orientation === \"slash\" ? startRow + step :\n            startRow + step;\n          const col =\n            orientation === \"horizontal\" ? startCol + step :\n            orientation === \"vertical\" ? startCol :\n            orientation === \"slash\" ? startCol - step :\n            startCol + step;\n          if (row < 0 || row >= rows || col < 0 || col >= cols) break;\n          cells.push(toIndex(row, col, cols));\n        }\n        cells.forEach((cell) => blockedSet.add(cell));\n      }\n\n      function collectRuns(rows, cols, blockedSet, orientation) {\n        const runs = [];\n        if (orientation === \"horizontal\") {\n          for (let row = 0; row < rows; row += 1) {\n            let current = [];\n            for (let col = 0; col < cols; col += 1) {\n              const index = toIndex(row, col, cols);\n              if (blockedSet.has(index)) {\n                if (current.length) runs.push(current);\n                current = [];\n              } else {\n                current.push(index);\n              }\n            }\n            if (current.length) runs.push(current);\n          }\n        } else {\n          for (let col = 0; col < cols; col += 1) {\n            let current = [];\n            for (let row = 0; row < rows; row += 1) {\n              const index = toIndex(row, col, cols);\n              if (blockedSet.has(index)) {\n                if (current.length) runs.push(current);\n                current = [];\n              } else {\n                current.push(index);\n              }\n            }\n            if (current.length) runs.push(current);\n          }\n        }\n        return runs;\n      }\n\n      function buildPatternLayout(rows, cols, seedLabel, wordSettings, layoutSettings) {\n        const targetBlocked = clamp(targetBlockedForLayout(rows, cols, layoutSettings), 0, rows * cols - 4);\n        const rng = makeRng(hashText(`${seedLabel}:pattern`));\n        let best = null;\n        for (let attempt = 0; attempt < 18; attempt += 1) {\n          const blocked = new Set();\n          while (blocked.size < targetBlocked) {\n            carveLineSegment(blocked, rows, cols, layoutSettings.mode, rng, targetBlocked - blocked.size);\n            if (blocked.size >= rows * cols - 4) break;\n          }\n          const orientation = layoutSettings.mode === \"horizontals\" ? \"vertical\" : \"horizontal\";\n          const runs = shuffle(collectRuns(rows, cols, blocked, orientation), rng);\n          const slotPaths = [];\n          const playableSet = new Set();\n\n          runs.forEach((run, runIndex) => {\n            if (run.length < 4) return;\n            const lengths = chooseWordLengthsForTotal(run.length, wordSettings, makeRng(hashText(`${seedLabel}:run:${attempt}:${runIndex}`)));\n            let offset = 0;\n            lengths.forEach((length) => {\n              if (offset + length > run.length) return;\n              const slot = run.slice(offset, offset + length);\n              slotPaths.push(slot);\n              slot.forEach((cell) => playableSet.add(cell));\n              offset += length;\n            });\n          });\n\n          const cells = Array.from({ length: rows * cols }, (_, index) => playableSet.has(index) ? { type: \"tile\" } : { type: \"block\" });\n          const result = { cells, slotPaths, playableCount: playableSet.size };\n          if (!best || result.playableCount > best.playableCount) best = result;\n          if (result.playableCount >= rows * cols - targetBlocked - 3) break;\n        }\n        return best || {\n          cells: Array.from({ length: rows * cols }, () => ({ type: \"block\" })),\n          slotPaths: [],\n          playableCount: 0\n        };\n      }\n\n      function buildDefaultLayout(rows, cols, seedLabel, wordSettings, layoutSettings) {\n        const targetBlocked =\n          layoutSettings.mode === \"no-blanks\"\n            ? 0\n            : clamp(targetBlockedForLayout(rows, cols, layoutSettings), 0, rows * cols - 4);\n        const targetPlayable = rows * cols - targetBlocked;\n        const rng = makeRng(hashText(`${seedLabel}:default`));\n        let best = null;\n\n        for (let attempt = 0; attempt < 24; attempt += 1) {\n          const lengths = chooseWordLengthsForTotal(targetPlayable, wordSettings, makeRng(hashText(`${seedLabel}:lengths:${attempt}`)));\n          const requiredTurningWords = requiredTurningWordCount(lengths);\n          const turningCandidates = shuffle(\n            lengths.map((length, index) => ({ length, index })).filter(({ length }) => length >= 3),\n            makeRng(hashText(`${seedLabel}:turns:${attempt}`))\n          ).slice(0, requiredTurningWords);\n          const turningSet = new Set(turningCandidates.map(({ index }) => index));\n          const occupied = new Set();\n          const slotPaths = [];\n          let failed = false;\n\n          for (let index = 0; index < lengths.length; index += 1) {\n            const path = placeRandomPath(lengths[index], occupied, rows, cols, rng, {\n              requireTurn: turningSet.has(index)\n            });\n            if (!path) {\n              failed = true;\n              break;\n            }\n            path.forEach((cell) => occupied.add(cell));\n            slotPaths.push(path);\n          }\n\n          if (!failed) {\n            if (countTurningPaths(slotPaths, cols) < requiredTurningWords) continue;\n            const cells = Array.from({ length: rows * cols }, (_, index) => occupied.has(index) ? { type: \"tile\" } : { type: \"block\" });\n            const result = { cells, slotPaths, playableCount: occupied.size };\n            if (!best || result.playableCount > best.playableCount) best = result;\n            if (occupied.size >= targetPlayable - 2) break;\n          }\n        }\n\n        if (best) return best;\n\n        const fallbackRng = makeRng(hashText(`${seedLabel}:fallback`));\n        const traversal = snakeTraversal(rows, cols, fallbackRng);\n        const slotPaths = splitTraversalIntoSlots(traversal, targetPlayable, wordSettings, cols, fallbackRng);\n        const playableSet = new Set(slotPaths.flat());\n        return {\n          cells: Array.from({ length: rows * cols }, (_, index) => playableSet.has(index) ? { type: \"tile\" } : { type: \"block\" }),\n          slotPaths,\n          playableCount: playableSet.size\n        };\n      }\n\n      function buildPlayableLayout(rows, cols, seedLabel, wordSettings, layoutSettings) {\n        if (layoutSettings.mode === \"default\" || layoutSettings.mode === \"no-blanks\") {\n          return buildDefaultLayout(rows, cols, seedLabel, wordSettings, layoutSettings);\n        }\n        return buildPatternLayout(rows, cols, seedLabel, wordSettings, layoutSettings);\n      }\n\n      function materializePuzzle(rows, cols, mode, seedKey) {\n        const wordSettings = currentWordSettings();\n        const layoutSettings = currentLayoutSettings(rows, cols);\n        const parsed = parseGameSeed(seedKey, mode === \"daily\" ? buildDailyBaseSeed() : \"practice-0\");\n        const fullSeed = composeGameSeed(parsed.baseSeed, rows, cols, wordSettings, layoutSettings);\n        const seedLabel = `${mode}:${fullSeed}`;\n        const layout = buildPlayableLayout(rows, cols, seedLabel, wordSettings, layoutSettings);\n        const cells = layout.cells.map((cell) => ({ ...cell }));\n        const words = layout.slotPaths.map((path, index) => ({\n          text: pickWord(path.length, index, seedLabel, wordSettings),\n          path\n        }));\n\n        words.forEach((word, wordIndex) => {\n          word.path.forEach((cellIndex, stepIndex) => {\n            cells[cellIndex] = {\n              ...cells[cellIndex],\n              type: \"tile\",\n              letter: word.text[stepIndex],\n              wordIndex,\n              step: stepIndex + 1\n            };\n          });\n        });\n\n        return {\n          id: `${mode}-${fullSeed}`,\n          name: `${rows}x${cols} ${mode === \"daily\" ? \"Daily Matrix\" : \"Practice Matrix\"}`,\n          seedKey: fullSeed,\n          rows,\n          cols,\n          cells,\n          words,\n          playableCount: words.reduce((sum, word) => sum + word.path.length, 0),\n          blankChar: layoutSettings.mode === \"no-blanks\" ? \"\" : layoutSettings.blankChar\n        };\n      }\n\n      function getDailyPuzzle() {\n        const { rows, cols } = currentGridSize();\n        return materializePuzzle(\n          rows,\n          cols,\n          \"daily\",\n          composeGameSeed(buildDailyBaseSeed(), rows, cols, currentWordSettings(), currentLayoutSettings(rows, cols))\n        );\n      }\n\n      function startPuzzle(puzzle, mode, options = {}) {\n        state.mode = mode;\n        state.puzzle = puzzle;\n        state.currentSeed = puzzle.seedKey;\n        setUrlSeed(puzzle.seedKey);\n        state.activePath = [];\n        state.invalidTiles = [];\n        state.draggingPointerId = null;\n        state.gestureExtended = false;\n        const saved = options.ignoreSavedState ? null : loadStateForPuzzle(puzzle);\n        state.foundWords = saved?.foundWords || [];\n        state.hints = saved?.hints || {};\n        state.startTime = saved?.startTime || Date.now();\n        state.message = \"Trace the exact hidden path for each word. Every playable tile must be claimed.\";\n        ensureTimer();\n        render();\n      }\n\n      function updateTimer() {\n        const elapsed = Math.floor((Date.now() - state.startTime) / 1000);\n        const minutes = String(Math.floor(elapsed / 60)).padStart(2, \"0\");\n        const seconds = String(elapsed % 60).padStart(2, \"0\");\n        els.timer.textContent = `${minutes}:${seconds}`;\n      }\n\n      function ensureTimer() {\n        if (state.timerHandle) clearInterval(state.timerHandle);\n        updateTimer();\n        state.timerHandle = setInterval(updateTimer, 1000);\n      }\n\n      function isSolvedWord(wordIndex) {\n        return state.foundWords.includes(wordIndex);\n      }\n\n      function isLockedTile(index) {\n        const cell = state.puzzle.cells[index];\n        return cell.type === \"tile\" && isSolvedWord(cell.wordIndex);\n      }\n\n      function isAdjacent(a, b) {\n        const [r1, c1] = toCoord(a, state.puzzle.cols);\n        const [r2, c2] = toCoord(b, state.puzzle.cols);\n        return Math.abs(r1 - r2) + Math.abs(c1 - c2) === 1;\n      }\n\n      function activeWordPath() {\n        return state.activePath.map((index) => state.puzzle.cells[index].letter).join(\"\");\n      }\n\n      function setMessage(text) {\n        state.message = text;\n        renderMessage();\n      }\n\n      function renderMessage() {\n        els.currentPath.textContent = activeWordPath() || \"—\";\n        els.messageText.textContent = state.message;\n      }\n\n      function clearInvalidTiles() {\n        if (state.invalidTiles.length === 0) return;\n        state.invalidTiles = [];\n        render();\n      }\n\n      function submitPath() {\n        if (state.activePath.length === 0) {\n          setMessage(\"Start a path before submitting.\");\n          return;\n        }\n\n        const matchedWordIndex = state.puzzle.words.findIndex((word, index) => {\n          if (isSolvedWord(index)) return false;\n          if (word.path.length !== state.activePath.length) return false;\n          return word.path.every((cellIndex, pathIndex) => cellIndex === state.activePath[pathIndex]);\n        });\n\n        if (matchedWordIndex === -1) {\n          state.invalidTiles = [...state.activePath];\n          state.activePath = [];\n          setMessage(\"That path is not one of the hidden answers.\");\n          render();\n          window.setTimeout(clearInvalidTiles, 420);\n          return;\n        }\n\n        state.foundWords = [...state.foundWords, matchedWordIndex].sort((a, b) => a - b);\n        state.activePath = [];\n        saveState();\n\n        if (state.foundWords.length === state.puzzle.words.length) {\n          setMessage(\"Solved. Every playable tile is accounted for.\");\n        } else {\n          const remaining = state.puzzle.words.length - state.foundWords.length;\n          setMessage(`Correct. ${remaining} word${remaining === 1 ? \"\" : \"s\"} remaining.`);\n        }\n        render();\n      }\n\n      function extendPath(index) {\n        const cell = state.puzzle.cells[index];\n        if (!cell || cell.type !== \"tile\" || isLockedTile(index)) return;\n        const last = state.activePath[state.activePath.length - 1];\n        const previous = state.activePath[state.activePath.length - 2];\n        if (last === index) return;\n        if (previous === index) {\n          state.activePath.pop();\n          state.gestureExtended = true;\n          renderMessage();\n          renderBoard();\n          return;\n        }\n        if (state.activePath.includes(index)) return;\n        if (last !== undefined && !isAdjacent(last, index)) return;\n        state.activePath.push(index);\n        if (last !== undefined) state.gestureExtended = true;\n        renderMessage();\n        renderBoard();\n      }\n\n      function beginPath(index, pointerId = null) {\n        clearInvalidTiles();\n        if (state.activePath.length === 0) {\n          state.activePath = [index];\n        } else {\n          extendPath(index);\n        }\n        state.draggingPointerId = pointerId;\n        state.gestureExtended = false;\n        setMessage(\"Build a path through orthogonally adjacent letters, then release or tap the end tile again to submit.\");\n        render();\n      }\n\n      function handlePointerDown(index, event) {\n        const cell = state.puzzle.cells[index];\n        if (!cell || cell.type !== \"tile\" || isLockedTile(index)) return;\n        beginPath(index, event.pointerId);\n      }\n\n      function handlePointerEnter(index, event) {\n        if (state.draggingPointerId !== event.pointerId) return;\n        extendPath(index);\n      }\n\n      function handlePointerUp(event) {\n        if (state.draggingPointerId !== event.pointerId) return;\n        if (state.gestureExtended && state.activePath.length > 0) submitPath();\n        state.draggingPointerId = null;\n        state.gestureExtended = false;\n      }\n\n      function handleTileClick(index) {\n        const cell = state.puzzle.cells[index];\n        if (!cell || cell.type !== \"tile\" || isLockedTile(index)) return;\n        const last = state.activePath[state.activePath.length - 1];\n        if (last === index && state.activePath.length > 1) {\n          submitPath();\n          return;\n        }\n        if (state.activePath.length === 0) {\n          state.activePath = [index];\n          setMessage(\"Tap adjacent letters to build a path, then tap the current end tile again to submit.\");\n        } else {\n          extendPath(index);\n        }\n        render();\n      }\n\n      function revealHint() {\n        const nextWordIndex = state.puzzle.words.findIndex((_, index) => !isSolvedWord(index));\n        if (nextWordIndex === -1) return;\n        const revealed = state.hints[nextWordIndex] || 0;\n        state.hints[nextWordIndex] = Math.min(state.puzzle.words[nextWordIndex].text.length, revealed + 1);\n        saveState();\n        setMessage(`Hint revealed for the next ${state.puzzle.words[nextWordIndex].text.length}-letter word.`);\n        render();\n      }\n\n      function undoPath() {\n        if (state.activePath.length === 0) return;\n        state.activePath.pop();\n        setMessage(\"Last step removed.\");\n        render();\n      }\n\n      function resetProgress() {\n        state.activePath = [];\n        state.foundWords = [];\n        state.hints = {};\n        state.invalidTiles = [];\n        state.startTime = Date.now();\n        saveState();\n        setMessage(\"Board reset. Start from any open tile.\");\n        render();\n      }\n\n      function solvePuzzle() {\n        state.activePath = [];\n        state.invalidTiles = [];\n        state.hints = {};\n        state.foundWords = state.puzzle.words.map((_, index) => index);\n        saveState();\n        setMessage(\"Puzzle solved. Every word has been revealed.\");\n        render();\n      }\n\n      function solvedWordSaturation(wordIndex) {\n        return 44 + (wordIndex * 11) % 40;\n      }\n\n      function solvedWordLightness(wordIndex) {\n        return wordIndex % 2 === 0 ? 34 : 58;\n      }\n\n      function solvedWordColor(wordIndex) {\n        const mode = state.selectedColorMode;\n        if (mode === \"hue\") return `hsl(${(wordIndex * 67 + 204) % 360} 62% 46%)`;\n        if (mode === \"saturation\") return `hsl(204 ${solvedWordSaturation(wordIndex)}% 44%)`;\n        if (mode === \"value\") return `hsl(204 62% ${solvedWordLightness(wordIndex)}%)`;\n        const hues = PALETTE_THEMES[mode] || PALETTE_THEMES[\"palette-citrus-grove\"];\n        const hue = hues[wordIndex % hues.length];\n        return `hsl(${hue} 68% 46%)`;\n      }\n\n      function solvedWordAccent(wordIndex) {\n        const mode = state.selectedColorMode;\n        if (mode === \"hue\") return `hsl(${(wordIndex * 67 + 204) % 360} 80% 76%)`;\n        if (mode === \"saturation\") return `hsl(204 ${Math.min(96, solvedWordSaturation(wordIndex) + 18)}% 70%)`;\n        if (mode === \"value\") return `hsl(204 78% ${wordIndex % 2 === 0 ? 72 : 28}%)`;\n        const hues = PALETTE_THEMES[mode] || PALETTE_THEMES[\"palette-citrus-grove\"];\n        const hue = hues[wordIndex % hues.length];\n        return `hsl(${hue} 86% 78%)`;\n      }\n\n      function arrowForStep(from, to, cols) {\n        if (to === undefined) return null;\n        const [r1, c1] = toCoord(from, cols);\n        const [r2, c2] = toCoord(to, cols);\n        if (r2 === r1 - 1) return \"↑\";\n        if (r2 === r1 + 1) return \"↓\";\n        if (c2 === c1 - 1) return \"←\";\n        if (c2 === c1 + 1) return \"→\";\n        return null;\n      }\n\n      function buildArrowMap() {\n        const solved = new Map();\n        const active = new Map();\n        const solvedEnds = new Set();\n        const activeEnds = new Set();\n\n        state.puzzle.words.forEach((word, wordIndex) => {\n          if (!isSolvedWord(wordIndex)) return;\n          for (let index = 0; index < word.path.length - 1; index += 1) {\n            const from = word.path[index];\n            const to = word.path[index + 1];\n            const arrow = arrowForStep(from, to, state.puzzle.cols);\n            solved.set(from, index === 0 ? `○${arrow}` : arrow);\n          }\n          solvedEnds.add(word.path[word.path.length - 1]);\n        });\n\n        for (let index = 0; index < state.activePath.length - 1; index += 1) {\n          const from = state.activePath[index];\n          const to = state.activePath[index + 1];\n          const arrow = arrowForStep(from, to, state.puzzle.cols);\n          active.set(from, index === 0 ? `○${arrow}` : arrow);\n        }\n        if (state.activePath.length > 0) activeEnds.add(state.activePath[state.activePath.length - 1]);\n\n        return { solved, active, solvedEnds, activeEnds };\n      }\n\n      function buildConnectorSegments() {\n        const solved = [];\n        const active = [];\n        state.puzzle.words.forEach((word, wordIndex) => {\n          if (!isSolvedWord(wordIndex)) return;\n          for (let index = 0; index < word.path.length - 1; index += 1) {\n            solved.push([word.path[index], word.path[index + 1], wordIndex]);\n          }\n        });\n        for (let index = 0; index < state.activePath.length - 1; index += 1) {\n          active.push([state.activePath[index], state.activePath[index + 1]]);\n        }\n        return { solved, active };\n      }\n\n      function computeTileMetrics() {\n        const cols = state.puzzle.cols;\n        const gap = cols >= 18 ? 2 : cols >= 14 ? 4 : cols >= 10 ? 6 : 8;\n        const boardWidth =\n          els.board.getBoundingClientRect().width ||\n          els.board.parentElement.getBoundingClientRect().width - 28;\n        const tileSize = (boardWidth - gap * (cols - 1)) / cols;\n        return {\n          gap,\n          tileSize,\n          fontSize: clamp(tileSize * 0.46, 8, 24),\n          hintSize: clamp(tileSize * 0.22, 6, 11),\n          arrowSize: clamp(tileSize * 0.24, 7, 12),\n          radius: clamp(tileSize * 0.2, 4, 18)\n        };\n      }\n\n      function renderBoard() {\n        if (!state.puzzle) return;\n        const metrics = computeTileMetrics();\n        els.board.style.gridTemplateColumns = `repeat(${state.puzzle.cols}, minmax(0, 1fr))`;\n        els.board.style.gap = `${metrics.gap}px`;\n        els.board.style.setProperty(\"--tile-font-size\", `${metrics.fontSize}px`);\n        els.board.style.setProperty(\"--tile-index-size\", `${metrics.hintSize}px`);\n        els.board.style.setProperty(\"--tile-arrow-size\", `${metrics.arrowSize}px`);\n        els.board.style.setProperty(\"--tile-radius\", `${metrics.radius}px`);\n        els.board.innerHTML = \"\";\n\n        const arrowMap = buildArrowMap();\n        const connectors = buildConnectorSegments();\n\n        function appendConnector(from, to, className, wordIndex = null) {\n          const [fromRow, fromCol] = toCoord(from, state.puzzle.cols);\n          const [toRow, toCol] = toCoord(to, state.puzzle.cols);\n          const step = metrics.tileSize + metrics.gap;\n          const x1 = fromCol * step + metrics.tileSize / 2;\n          const y1 = fromRow * step + metrics.tileSize / 2;\n          const x2 = toCol * step + metrics.tileSize / 2;\n          const y2 = toRow * step + metrics.tileSize / 2;\n          const dx = x2 - x1;\n          const dy = y2 - y1;\n          const length = Math.hypot(dx, dy);\n          const angle = Math.atan2(dy, dx) * 180 / Math.PI;\n          const thickness = Math.max(8, metrics.tileSize * 0.24);\n\n          const connector = document.createElement(\"div\");\n          connector.className = `path-connector ${className}`;\n          if (className === \"solved\" && wordIndex !== null) {\n            connector.style.background = solvedWordAccent(wordIndex);\n          }\n          connector.style.width = `${length}px`;\n          connector.style.height = `${thickness}px`;\n          connector.style.left = `${x1}px`;\n          connector.style.top = `${y1 - thickness / 2}px`;\n          connector.style.transformOrigin = \"0 50%\";\n          connector.style.transform = `rotate(${angle}deg)`;\n          els.board.appendChild(connector);\n        }\n\n        connectors.solved.forEach(([from, to, wordIndex]) => appendConnector(from, to, \"solved\", wordIndex));\n        connectors.active.forEach(([from, to]) => appendConnector(from, to, \"active\"));\n\n        state.puzzle.cells.forEach((cell, index) => {\n          if (cell.type === \"block\") {\n            const block = document.createElement(\"div\");\n            block.className = \"block\";\n            if (state.puzzle.blankChar) {\n              block.textContent = state.puzzle.blankChar;\n              block.setAttribute(\"aria-hidden\", \"true\");\n            }\n            els.board.appendChild(block);\n            return;\n          }\n\n          const button = document.createElement(\"button\");\n          button.type = \"button\";\n          button.className = \"tile\";\n          button.setAttribute(\"aria-label\", `Letter ${cell.letter}`);\n\n          const letter = document.createElement(\"span\");\n          letter.className = \"tile-letter\";\n          letter.textContent = cell.letter;\n          button.appendChild(letter);\n\n          if (state.activePath.includes(index)) button.classList.add(\"active\");\n          if (isSolvedWord(cell.wordIndex)) {\n            button.classList.add(\"found\", \"locked\");\n            button.style.background = solvedWordColor(cell.wordIndex);\n            button.style.borderColor = solvedWordAccent(cell.wordIndex);\n          }\n          if (state.invalidTiles.includes(index)) button.classList.add(\"invalid\");\n          if ((state.hints[cell.wordIndex] || 0) >= cell.step && !isSolvedWord(cell.wordIndex)) {\n            button.classList.add(\"hinted\");\n          }\n\n          const badge = document.createElement(\"span\");\n          badge.className = \"tile-index\";\n          if ((state.hints[cell.wordIndex] || 0) >= cell.step && !isSolvedWord(cell.wordIndex)) {\n            badge.textContent = cell.step;\n          }\n          button.appendChild(badge);\n\n          const activeArrow = arrowMap.active.get(index);\n          const solvedArrow = arrowMap.solved.get(index);\n          const arrow = activeArrow || solvedArrow;\n          if (arrow) {\n            const arrowEl = document.createElement(\"span\");\n            arrowEl.className = `path-arrow ${activeArrow ? \"active\" : \"solved\"}`;\n            arrowEl.textContent = arrow;\n            if (!activeArrow && isSolvedWord(cell.wordIndex)) arrowEl.style.color = solvedWordAccent(cell.wordIndex);\n            button.appendChild(arrowEl);\n          }\n\n          const isActiveEnd = arrowMap.activeEnds.has(index);\n          const isSolvedEnd = arrowMap.solvedEnds.has(index);\n          if (isActiveEnd || isSolvedEnd) {\n            const endEl = document.createElement(\"span\");\n            endEl.className = `path-end ${isActiveEnd ? \"active\" : \"solved\"}`;\n            endEl.textContent = \"●\";\n            if (!isActiveEnd && isSolvedWord(cell.wordIndex)) endEl.style.color = solvedWordAccent(cell.wordIndex);\n            button.appendChild(endEl);\n          }\n\n          button.addEventListener(\"pointerdown\", (event) => handlePointerDown(index, event));\n          button.addEventListener(\"pointerenter\", (event) => handlePointerEnter(index, event));\n          button.addEventListener(\"pointerup\", handlePointerUp);\n          button.addEventListener(\"click\", () => handleTileClick(index));\n          els.board.appendChild(button);\n        });\n      }\n\n      function hintedDisplay(word, wordIndex) {\n        const count = state.hints[wordIndex] || 0;\n        return word.text\n          .split(\"\")\n          .map((letter, index) => (index < count ? letter : \"•\"))\n          .join(\" \");\n      }\n\n      function renderSlots() {\n        els.slots.innerHTML = \"\";\n        state.puzzle.words.forEach((word, index) => {\n          const solved = isSolvedWord(index);\n          const slot = document.createElement(\"div\");\n          slot.className = `slot${solved ? \" solved\" : \"\"}`;\n\n          const header = document.createElement(\"div\");\n          header.className = \"slot-header\";\n\n          const left = document.createElement(\"span\");\n          left.textContent = `${word.text.length} letters`;\n\n          const right = document.createElement(\"span\");\n          right.textContent = solved ? \"Solved\" : \"Hidden\";\n\n          const value = document.createElement(\"div\");\n          value.className = \"slot-value\";\n          value.textContent = solved ? word.text.split(\"\").join(\" \") : hintedDisplay(word, index);\n\n          header.append(left, right);\n          slot.append(header, value);\n          els.slots.appendChild(slot);\n        });\n      }\n\n      function renderSummary() {\n        els.modePill.textContent = state.mode === \"daily\" ? \"Daily puzzle\" : \"Practice puzzle\";\n        els.puzzlePill.textContent = `${state.puzzle.name} • ${state.puzzle.playableCount} playable`;\n        els.foundCount.textContent = `${state.foundWords.length} / ${state.puzzle.words.length}`;\n        els.hintCount.textContent = String(Object.values(state.hints).reduce((sum, value) => sum + value, 0));\n        els.gridSize.value = state.selectedGridSize;\n        els.seedInput.value = state.currentSeed;\n        els.wordMode.value = state.selectedWordMode;\n        els.requiredTextInput.value = state.selectedRequiredText;\n        els.startLetterInput.value = state.selectedStartLetter;\n        els.fixedLengthInput.value = String(sanitizeFixedLength(state.selectedFixedLength));\n        els.blankLayout.value = state.selectedBlankLayout;\n        els.blankPercentInput.value = String(sanitizeBlankPercent(state.selectedBlankPercent));\n        els.blankCountInput.value = String(sanitizeBlankCount(state.selectedBlankCount, state.puzzle.rows, state.puzzle.cols));\n        els.blankCharInput.value = sanitizeBlankChar(state.selectedBlankChar);\n        els.requiredTextField.hidden = state.selectedWordMode !== \"contains-text\";\n        els.startLetterField.hidden = state.selectedWordMode !== \"starts-with\";\n        els.fixedLengthField.hidden = state.selectedWordMode !== \"fixed-length\";\n        const showBlankControls = blankControlsRelevant(state.selectedBlankLayout);\n        els.blankPercentField.hidden = !showBlankControls;\n        els.blankCountField.hidden = !showBlankControls;\n        els.blankCharField.hidden = !showBlankControls;\n        els.colorMode.value = state.selectedColorMode;\n        const solved = state.foundWords.length === state.puzzle.words.length;\n        els.successBanner.hidden = !solved;\n        if (solved) {\n          els.successText.textContent = `Solved in ${els.timer.textContent} with ${els.hintCount.textContent} hint(s).`;\n        }\n      }\n\n      function render() {\n        renderBoard();\n        renderSlots();\n        renderSummary();\n        renderMessage();\n      }\n\n      function selectSettingsTab(tab) {\n        Object.entries(els.settingsPanels).forEach(([key, panel]) => {\n          panel.hidden = key !== tab;\n        });\n        els.settingsTabButtons.forEach((button) => {\n          button.classList.toggle(\"is-active\", button.dataset.tab === tab);\n        });\n      }\n\n      function openSettings(tab = \"game\") {\n        selectSettingsTab(tab);\n        if (els.appMenu) els.appMenu.open = false;\n        els.settingsOverlay.hidden = false;\n      }\n\n      function closeSettings() {\n        els.settingsOverlay.hidden = true;\n      }\n\n      function syncConfigFromControls() {\n        state.selectedWordMode = els.wordMode.value;\n        state.selectedRequiredText = sanitizeRequiredText(els.requiredTextInput.value);\n        state.selectedStartLetter = sanitizeStartLetter(els.startLetterInput.value);\n        state.selectedFixedLength = sanitizeFixedLength(els.fixedLengthInput.value);\n        state.selectedBlankLayout = els.blankLayout.value;\n        const { rows, cols } = currentGridSize();\n        state.selectedBlankPercent = sanitizeBlankPercent(els.blankPercentInput.value);\n        state.selectedBlankCount = sanitizeBlankCount(els.blankCountInput.value, rows, cols);\n        state.selectedBlankChar = sanitizeBlankChar(els.blankCharInput.value);\n      }\n\n      function buildCurrentSeed(baseSeed) {\n        const { rows, cols } = currentGridSize();\n        return composeGameSeed(baseSeed, rows, cols, currentWordSettings(), currentLayoutSettings(rows, cols));\n      }\n\n      function nextPracticePuzzle() {\n        syncConfigFromControls();\n        if (els.appMenu) els.appMenu.open = false;\n        state.practiceIndex += 1;\n        startPuzzle(materializePuzzle(currentGridSize().rows, currentGridSize().cols, \"practice\", buildCurrentSeed(buildPracticeBaseSeed(state.practiceIndex))), \"practice\", { ignoreSavedState: true });\n      }\n\n      function regenerateCurrentMode() {\n        const { rows, cols } = currentGridSize();\n        const parsed = parseGameSeed(state.currentSeed, state.mode === \"daily\" ? buildDailyBaseSeed() : \"practice-0\");\n        const baseSeed = state.mode === \"daily\" ? buildDailyBaseSeed() : parsed.baseSeed;\n        startPuzzle(materializePuzzle(rows, cols, state.mode, buildCurrentSeed(baseSeed)), state.mode);\n      }\n\n      function applyGridSize(value) {\n        state.selectedGridSize = value;\n        regenerateCurrentMode();\n      }\n\n      function applyWordSettings() {\n        state.selectedWordMode = els.wordMode.value;\n        state.selectedRequiredText = sanitizeRequiredText(els.requiredTextInput.value);\n        state.selectedStartLetter = sanitizeStartLetter(els.startLetterInput.value);\n        state.selectedFixedLength = sanitizeFixedLength(els.fixedLengthInput.value);\n        renderSummary();\n        if (state.selectedWordMode === \"contains-text\" || state.selectedWordMode === \"starts-with\" || state.selectedWordMode === \"fixed-length\") {\n          setMessage(\"Choose the extra word filter, then the board will regenerate.\");\n          if (state.selectedWordMode === \"contains-text\" && !state.selectedRequiredText) return;\n          if (state.selectedWordMode === \"starts-with\" && !state.selectedStartLetter) return;\n          return;\n        }\n        regenerateCurrentMode();\n      }\n\n      function applyLayoutSettings() {\n        state.selectedBlankLayout = els.blankLayout.value;\n        syncConfigFromControls();\n        renderSummary();\n        regenerateCurrentMode();\n      }\n\n      function applySeedInput() {\n        syncConfigFromControls();\n        const fallbackBase = els.seedInput.value.startsWith(\"daily-\") ? buildDailyBaseSeed() : \"practice-0\";\n        const { rows, cols, mode, fullSeed } = applySeedConfiguration(els.seedInput.value, fallbackBase);\n        state.practiceIndex = 0;\n        startPuzzle(materializePuzzle(rows, cols, mode, fullSeed), mode);\n      }\n\n      function applyColorMode(value) {\n        state.selectedColorMode = value;\n        render();\n      }\n\n      function populateGridSizeOptions() {\n        els.gridSize.innerHTML = \"\";\n        for (let size = GRID_MIN; size <= GRID_MAX; size += 1) {\n          const option = document.createElement(\"option\");\n          option.value = `${size}x${size}`;\n          option.textContent = `${size} x ${size}`;\n          els.gridSize.appendChild(option);\n        }\n      }\n\n      els.practiceBtn.addEventListener(\"click\", nextPracticePuzzle);\n      els.settingsOpenBtn.addEventListener(\"click\", () => openSettings(\"game\"));\n      els.settingsCloseBtn.addEventListener(\"click\", closeSettings);\n      els.settingsOverlay.addEventListener(\"click\", (event) => {\n        if (event.target === els.settingsOverlay) closeSettings();\n      });\n      els.settingsTabButtons.forEach((button) => {\n        button.addEventListener(\"click\", () => selectSettingsTab(button.dataset.tab));\n      });\n      els.undoBtn.addEventListener(\"click\", undoPath);\n      els.hintBtn.addEventListener(\"click\", revealHint);\n      els.solveBtn.addEventListener(\"click\", solvePuzzle);\n      els.resetBtn.addEventListener(\"click\", resetProgress);\n      els.seedApplyBtn.addEventListener(\"click\", applySeedInput);\n      els.seedInput.addEventListener(\"keydown\", (event) => {\n        if (event.key === \"Enter\") applySeedInput();\n      });\n      els.gridSize.addEventListener(\"change\", (event) => applyGridSize(event.target.value));\n      els.wordMode.addEventListener(\"change\", applyWordSettings);\n      els.requiredTextInput.addEventListener(\"input\", () => {\n        state.selectedRequiredText = sanitizeRequiredText(els.requiredTextInput.value);\n        if (state.selectedWordMode === \"contains-text\") {\n          renderSummary();\n          if (!state.selectedRequiredText) {\n            setMessage(\"Enter the required letter or letters to regenerate this mode.\");\n            return;\n          }\n          regenerateCurrentMode();\n        } else {\n          renderSummary();\n        }\n      });\n      els.startLetterInput.addEventListener(\"input\", () => {\n        state.selectedStartLetter = sanitizeStartLetter(els.startLetterInput.value);\n        if (state.selectedWordMode === \"starts-with\") {\n          renderSummary();\n          if (!state.selectedStartLetter) {\n            setMessage(\"Enter the starting letter to regenerate this mode.\");\n            return;\n          }\n          regenerateCurrentMode();\n        } else {\n          renderSummary();\n        }\n      });\n      els.fixedLengthInput.addEventListener(\"change\", () => {\n        if (state.selectedWordMode === \"fixed-length\") {\n          state.selectedFixedLength = sanitizeFixedLength(els.fixedLengthInput.value);\n          renderSummary();\n          regenerateCurrentMode();\n        } else {\n          renderSummary();\n        }\n      });\n      els.blankLayout.addEventListener(\"change\", applyLayoutSettings);\n      els.blankPercentInput.addEventListener(\"change\", () => {\n        els.blankCountInput.value = \"0\";\n        applyLayoutSettings();\n      });\n      els.blankCountInput.addEventListener(\"change\", applyLayoutSettings);\n      els.blankCharInput.addEventListener(\"input\", applyLayoutSettings);\n      els.colorMode.addEventListener(\"change\", (event) => applyColorMode(event.target.value));\n      window.addEventListener(\"keydown\", (event) => {\n        if (event.key === \"Escape\" && !els.settingsOverlay.hidden) closeSettings();\n      });\n      window.addEventListener(\"pointerup\", handlePointerUp);\n      window.addEventListener(\"resize\", renderBoard);\n\n      populateGridSizeOptions();\n      const urlSeed = getUrlSeed();\n      if (urlSeed) {\n        const fallbackBase = urlSeed.startsWith(\"daily-\") ? buildDailyBaseSeed() : \"practice-0\";\n        const { rows, cols, mode, fullSeed } = applySeedConfiguration(urlSeed, fallbackBase);\n        startPuzzle(materializePuzzle(rows, cols, mode, fullSeed), mode);\n      } else {\n        startPuzzle(getDailyPuzzle(), \"daily\");\n      }\n    </script>\n  </body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/favicon.ico") {
      return new Response(null, { status: 204 });
    }

    return new Response(HTML, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store"
      }
    });
  }
};
